import sys,difflib,re
L=open(sys.argv[1],encoding='utf-8',errors='replace').read().split('\n')
i=0
minus=[];plus=[]
def flush():
    global minus,plus
    if minus or plus:
        a=' '.join(m[1:] for m in minus); b=' '.join(p[1:] for p in plus)
        ta=re.findall(r'\S+|\s+',a); tb=re.findall(r'\S+|\s+',b)
        sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op!='equal':
                ctxl=''.join(ta[max(0,i1-25):i1])
                print(f"  [{op}] ...{ctxl[-160:]}\n     OLD: {''.join(ta[i1:i2])!r}\n     NEW: {''.join(tb[j1:j2])!r}")
    minus=[];plus=[]
for l in L:
    if l.startswith('@@'):
        flush(); print('\n'+l[:130])
    elif l.startswith('-') and not l.startswith('---'): minus.append(l)
    elif l.startswith('+') and not l.startswith('+++'): plus.append(l)
    else: flush()
flush()
EOF

